import{_ as p,a0 as o,w as r,s as d,ao as l,I as t,x as i,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"七个改变我生活的 Git 小技巧 | LCTT x X-CMD","titleTemplate":false,"description":"七个改变我生活的 Git 小技巧 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"七个改变我生活的 Git 小技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"七个改变我生活的 Git 小技巧 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20201026 7 Git tricks that changed my life","title":"七个改变我生活的 Git 小技巧","tag":"202106","desc":""},"relativePath":"202106/20201026 7 Git tricks that changed my life.md","filePath":"[post].md"}'),g={name:"202106/20201026 7 Git tricks that changed my life.md"};function h(k,s,u,b,c,f){const a=o("Link");return r(),d("div",null,[s[34]||(s[34]=l(`<h1 id="七个改变我生活的-git-小技巧" tabindex="-1">七个改变我生活的 Git 小技巧 <a class="header-anchor" href="#七个改变我生活的-git-小技巧" aria-label="Permalink to “七个改变我生活的 Git 小技巧”">​</a></h1><blockquote><p>这些有用的小技巧将改变你在当前最流行的版本控制系统下的工作方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/28/110029d64pblurlh5a4a50.jpg" alt=""></p><p>Git 是当前最流行最普遍的版本控制系统之一，它被应用于私有系统和公开网站上各种各样的开发工作。不论我变得对 Git 有多熟悉，似乎总有些功能等待着被发掘。下面分享下和 Git 相关的改变我工作方式的一些小技巧。</p><h3 id="_1、git-中的自动纠错" tabindex="-1">1、Git 中的自动纠错 <a class="header-anchor" href="#_1、git-中的自动纠错" aria-label="Permalink to “1、Git 中的自动纠错”">​</a></h3><p>我们每个人都不时在输入时犯拼写错误，但是如果你使能了 Git 的自动纠错功能，你就能让 Git 自动纠正一些输入错误的子命令。</p><p>假如你想用命令 <code>git status</code> 来检查状态，但是你恰巧错误地输入了 <code>git stats</code>。通常情况下，Git 会告诉你 ‘stats’ 不是个有效的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stats</span></span>
<span class="line"><span>git: ‘stats’ is not a git command. See ‘git --help’.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The most similar command is</span></span>
<span class="line"><span>status</span></span></code></pre></div><p>为了避免类似情形，只需要在你的 Git 配置中使能自动纠错功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global help.autocorrect 1</span></span></code></pre></div><p>如果你只想对当前的仓库生效，就省略掉选项 <code>--global</code>。</p>`,11)),t("p",null,[s[1]||(s[1]=i("这个命令会使能自动纠错功能。在相应的 ",-1)),e(a,{href:"https://git-scm.com/book/en/v2/Customizing-Git-Git-Configuration#_code_help_autocorrect_code"},{default:n(()=>[...s[0]||(s[0]=[i("Git 官方文档",-1)])]),_:1}),s[2]||(s[2]=i(" 中可以看到这个命令的详细说明，但是试着敲一下上面的错误命令会使你对这个设置干了什么有个直观的了解：",-1))]),s[35]||(s[35]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stats</span></span>
<span class="line"><span>git: ‘stats’ is not a git command. See ‘git --help’.</span></span>
<span class="line"><span>On branch master</span></span>
<span class="line"><span>Your branch is up to date with ‘origin/master’.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nothing to commit, working tree clean</span></span></code></pre></div><p>在上面的例子中，Git 直接运行了它建议命令的第一个，也就是 <code>git status</code>，而不是给你展示它所建议的子命令。</p><h3 id="_2、对提交进行计数" tabindex="-1">2、对提交进行计数 <a class="header-anchor" href="#_2、对提交进行计数" aria-label="Permalink to “2、对提交进行计数”">​</a></h3><p>需要对提交进行计数的原因有很多。例如，一些开发人员利用提交计数来判断什么时候递增工程构建序号，也有一些开发人员用提交计数来对项目进展取得一个整体上的感观。</p><p>对提交进行计数相当简单而且直接，下面就是相应的 Git 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list --count branch-name</span></span></code></pre></div><p>在上述命令中，参数 <code>branch-name</code> 必须是一个你当前仓库里的有效分支名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list –count master</span></span>
<span class="line"><span>32</span></span>
<span class="line"><span>$ git rev-list –count dev</span></span>
<span class="line"><span>34</span></span></code></pre></div><h3 id="_3、仓库优化" tabindex="-1">3、仓库优化 <a class="header-anchor" href="#_3、仓库优化" aria-label="Permalink to “3、仓库优化”">​</a></h3>`,9)),t("p",null,[s[4]||(s[4]=i("你的代码仓库不仅对你来说很宝贵，对你所在的组织也一样。通过少数几个惯例你就能使自己的仓库整洁并且保持最新。",-1)),e(a,{href:"https://opensource.com/article/20/8/dont-ignore-gitignore"},{default:n(()=>[...s[3]||(s[3]=[i("使用 .gitignore 文件",-1)])]),_:1}),s[5]||(s[5]=i(" 就是这些最好的惯例之一。通过使用这个文件你可以告诉 Git 不要保存一些不需要记录的文件，如二进制文件、临时文件等等。",-1))]),s[36]||(s[36]=l(`<p>当然，你还可以使用 Git 的垃圾回收来进一步优化你的仓库。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git gc --prune=now --aggressive</span></span></code></pre></div><p>这个命令在你和你的团队经常使用 <code>pull</code> 或者 <code>push</code> 操作的时候很有帮助。</p><p>它是一个内部工具，能清理掉你的仓库里没法访问或者说“空悬”的 Git 对象。</p><h3 id="_4、给未追踪的文件来个备份" tabindex="-1">4、给未追踪的文件来个备份 <a class="header-anchor" href="#_4、给未追踪的文件来个备份" aria-label="Permalink to “4、给未追踪的文件来个备份”">​</a></h3><p>大多数时候，删除所有未追踪的文件是安全的。但很多时候也有这么一种场景，你想删掉这些未追踪的文件同时也想做个备份防止以后需要用到。</p><p>Git 组合一些 Bash 命令和管道操作，可以让你可以很容易地给那些未追踪的文件创建 zip 压缩包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git ls-files --others --exclude-standard -z |\\</span></span>
<span class="line"><span>  xargs -0 tar rvf ~/backup-untracked.zip</span></span></code></pre></div><p>上面的命令就生成了一个名字为 <code>backup-untracked.zip</code> 的压缩包文件（当然，在 <code>.gitignore</code> 里面忽略了的文件不会包含在内）。</p><h3 id="_5、了解你的-git-文件夹" tabindex="-1">5、了解你的 .git 文件夹 <a class="header-anchor" href="#_5、了解你的-git-文件夹" aria-label="Permalink to “5、了解你的 .git 文件夹”">​</a></h3><p>每个仓库都有一个 <code>.git</code> 文件夹，它是一个特殊的隐藏文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -a</span></span>
<span class="line"><span>. … .git</span></span></code></pre></div><p>Git 主要通过两个东西来工作：</p><ol><li>当前工作树（你当前检出的文件状态）</li><li>你的 Git 仓库的文件夹（准确地说，包含版本信息的 <code>.git</code> 文件夹的位置）</li></ol><p>这个文件夹存储了所有参考信息和一些其他的如配置、仓库数据、HEAD 状态、日志等更多诸如此类的重要细节。</p><p>一旦你删除了这个文件夹，尽管你的源码没被删，但是类似你的工程历史记录等远程信息就没有了。删除这个文件夹意味着你的工程（至少本地的复制）不再在版本控制的范畴之内了。这也就意味着你没法追踪你的修改；你没法从远程仓拉取或推送到远程仓了。</p><p>通常而言，你需要或者应当对你的 <code>.git</code> 文件夹的操作并不多。它是被 Git 管理的，而且大多数时候是一个禁区。然而，在这个文件夹内还是有一些有趣的工件，比如说当前的 HEAD 状态在内的就在其中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/HEAD</span></span>
<span class="line"><span>ref: refs/heads/master</span></span></code></pre></div><p>它也隐含着对你仓库地描述：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/description</span></span></code></pre></div><p>这是一个未命名的仓库；通过编辑文件 ‘description’ 可以给这个仓库命名。</p>`,21)),t("p",null,[s[7]||(s[7]=i("Git 钩子文件夹连同一些钩子文件例子也在这里。参考这些例子你就能知道 Git 钩子能干什么了。当然，你也可以 ",-1)),e(a,{href:"https://opensource.com/life/16/8/how-construct-your-own-git-server-part-6"},{default:n(()=>[...s[6]||(s[6]=[i("参考这个 Seth Kenlon 写的 Git 钩子介绍",-1)])]),_:1}),s[8]||(s[8]=i("。",-1))]),s[37]||(s[37]=t("h3",{id:"_6、浏览另一个分支的文件",tabindex:"-1"},[i("6、浏览另一个分支的文件 "),t("a",{class:"header-anchor",href:"#_6、浏览另一个分支的文件","aria-label":"Permalink to “6、浏览另一个分支的文件”"},"​")],-1)),s[38]||(s[38]=t("p",null,"有时，你会想要浏览另一个分支下某个文件的内容。这其实用一个简单的 Git 命令就可以实现，甚至都不用切换分支。",-1)),t("p",null,[s[10]||(s[10]=i("设想你有一个命名为 ",-1)),e(a,{href:"http://README.md"},{default:n(()=>[...s[9]||(s[9]=[i("README.md",-1)])]),_:1}),s[11]||(s[11]=i(" 的文件，并且它在 ",-1)),s[12]||(s[12]=t("code",null,"main",-1)),s[13]||(s[13]=i(" 分支上。当前你正工作在一个名为 ",-1)),s[14]||(s[14]=t("code",null,"dev",-1)),s[15]||(s[15]=i(" 的分支。",-1))]),s[39]||(s[39]=l(`<p>用下面的 Git 命令，在终端上就行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git show main:README.md</span></span></code></pre></div><p>一旦你执行这个命令，你就能在你的终端上看到 <code>main</code> 分支上该文件的内容。</p><h3 id="_7、git-中的搜索" tabindex="-1">7、Git 中的搜索 <a class="header-anchor" href="#_7、git-中的搜索" aria-label="Permalink to “7、Git 中的搜索”">​</a></h3><p>用一个简单的命令你就能在 Git 中像专业人士一样搜索了。更有甚者，尽管你不确定你的修改在哪次提交或者哪个分支上，你依然能搜索。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list --all | xargs git grep -F &#39;&#39;</span></span></code></pre></div><p>例如，假设你想在你的仓库中搜索字符串 <code>“font-size: 52 px;&quot;</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list –all | xargs git grep -F ‘font-size: 52 px;’</span></span>
<span class="line"><span>F3022…9e12:HtmlTemplate/style.css: font-size: 52 px;</span></span>
<span class="line"><span>E9211…8244:RR.Web/Content/style/style.css: font-size: 52 px;</span></span></code></pre></div><h3 id="试试这些小技巧" tabindex="-1">试试这些小技巧 <a class="header-anchor" href="#试试这些小技巧" aria-label="Permalink to “试试这些小技巧”">​</a></h3><p>我希望这些小技巧对你是有用的，或者增加你的生产力或者节省你的大量时间。</p>`,10)),t("p",null,[s[17]||(s[17]=i("你也有一些喜欢的 ",-1)),e(a,{href:"https://acompiler.com/git-tips/"},{default:n(()=>[...s[16]||(s[16]=[i("Git 技巧",-1)])]),_:1}),s[18]||(s[18]=i(" 吗？在评论区分享吧。",-1))]),s[40]||(s[40]=t("hr",null,null,-1)),t("p",null,[s[20]||(s[20]=i("via: ",-1)),e(a,{href:"https://opensource.com/article/20/10/advanced-git-tips"},{default:n(()=>[...s[19]||(s[19]=[i("https://opensource.com/article/20/10/advanced-git-tips",-1)])]),_:1})]),t("p",null,[s[25]||(s[25]=i("作者：",-1)),e(a,{href:"https://opensource.com/users/acompiler"},{default:n(()=>[...s[21]||(s[21]=[i("Rajeev Bera",-1)])]),_:1}),s[26]||(s[26]=i(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[22]||(s[22]=[i("lujun9972",-1)])]),_:1}),s[27]||(s[27]=i(" 译者：",-1)),e(a,{href:"https://github.com/BoosterY"},{default:n(()=>[...s[23]||(s[23]=[i("BoosterY",-1)])]),_:1}),s[28]||(s[28]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[24]||(s[24]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[31]||(s[31]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[29]||(s[29]=[i("LCTT",-1)])]),_:1}),s[32]||(s[32]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[30]||(s[30]=[i("Linux中国",-1)])]),_:1}),s[33]||(s[33]=i(" 荣誉推出",-1))])])}const v=p(g,[["render",h]]);export{y as __pageData,v as default};
